  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:skladniki-obowiazkowe-w-kazdym-ujeciu-z-ludz', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 101, date '2026-10-27', 'people', array['plan', 'prompt']::text[], 'shot_type', array['person', 'hands', 'animal']::text[], 'knowledge', false, 'Składniki obowiązkowe w każdym ujęciu z ludźmi', 'Składniki obowiązkowe w każdym ujęciu z ludźmi: konkretna czynność w toku, wyraźna emocja (śmiech, skupienie, satysfakcja, zachwyt), światło z kierunkiem i cieniem w kadrze, kolor ubrania dobrany celowo, tło spokojniejsze niż produkt.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:efekty-wizualne-podkreslajace-dzialanie-sa-p', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 102, date '2026-10-27', 'creative', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Efekty wizualne podkreślające działanie są pożądane', 'Efekty wizualne podkreślające działanie są pożądane (para, krople, przepływ, wióry, kurz, fale), ze smakiem i bez napisów. Napisy, plakietki i opisane powiększenia należą do przyszłego narzędzia z grafikami reklamowymi.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:kontrola-anty-stock-przed-kazdym-promptem', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 103, date '2026-10-27', 'anti_stock', array['plan']::text[], 'global', '{}'::text[], 'template', false, 'Kontrola anty-stock przed każdym promptem', 'Kontrola anty-stock przed każdym promptem: czy wiadomo, co się dzieje w tej sekundzie? czy ktoś coś czuje? czy światło ma kierunek i porę dnia? czy widać efekt działania? czy kadr jest ciekawszy niż „produkt na środku blatu”? Jeśli na dwa pytania odpowiedź brzmi nie, scena idzie do przepisania.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:zroznicowanie-swiatla-w-zestawie', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 104, date '2026-10-27', 'light_color', array['plan']::text[], 'global', '{}'::text[], 'code', false, 'Zróżnicowanie światła w zestawie', 'Zróżnicowanie światła w zestawie: maksymalnie 2 ujęcia w złotej godzinie. Reszta: chłodny poranek, niebieska godzina, kinowy półmrok, rozproszone światło pochmurnego dnia, noc z lampką. Ta sama tonacja w ponad połowie zdjęć = wygląd stockowy.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:elektronika-i-sprzet-zdrowotny', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 105, date '2026-10-27', 'light_color', array['plan', 'prompt']::text[], 'category', array['elektronik', 'zdrowot', 'inhalator', 'nawilzacz', 'oczyszczacz', 'cisnieniomierz', 'termometr', 'czujnik', 'czad', 'detektor']::text[], 'knowledge', false, 'Elektronika i sprzęt zdrowotny', 'Elektronika i sprzęt zdrowotny: neutralne lub chłodne, czyste światło, kontrast, produkt najjaśniejszym punktem. Ciepło tylko jako akcent (lampka), nigdy jako filtr na całym zdjęciu.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:korekta-czujnik-czadu-29-10', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 106, date '2026-10-29', 'light_color', array['plan', 'prompt']::text[], 'category', array['elektronik', 'zdrowot', 'inhalator', 'nawilzacz', 'oczyszczacz', 'cisnieniomierz', 'termometr', 'czujnik', 'czad', 'detektor']::text[], 'knowledge', true, 'Korekta (czujnik czadu, 29.10)', 'Korekta (czujnik czadu, 29.10): „chłodne i czyste” nie znaczy ciemne i szare. Cały zestaw w chłodnym półmroku wygląda ponuro, tanio i nie budzi zaufania. Domyślnie: jasne, naturalne światło dnia i wnętrza pełne życia; noc i półmrok tylko w 1–2 ujęciach i zawsze z ciepłymi źródłami światła (lampy, kominek, ekran) oraz kolorowymi akcentami.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:produkty-pasywne-i-bezpieczenstwa', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 107, date '2026-10-27', 'creative', array['plan', 'prompt']::text[], 'category', array['czujnik', 'czad', 'gasnic', 'alarm', 'bezpieczen', 'detektor']::text[], 'knowledge', false, 'Produkty pasywne i bezpieczeństwa', 'Produkty pasywne i bezpieczeństwa (czujniki, zamki, gaśnice): produkt sam niczego nie robi, więc zdjęcie sprzedaje życie, które chroni. Ludzie w centrum, w trakcie czynności, z pozytywną emocją (spokój, radość, bliskość), produkt ostry i czytelny w kadrze. Zagrożenie najwyżej w jednym ujęciu i pokazane przez spokojną reakcję, nie przez strach. Pusta ściana z produktem w roli głównej = stock.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:wzorzec-ktory-dziala-czujnik-czadu-akceptowa', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 108, date '2026-10-27', 'creative', array['plan', 'prompt']::text[], 'category', array['czujnik', 'czad', 'gasnic', 'alarm', 'bezpieczen', 'detektor']::text[], 'knowledge', false, 'Wzorzec, który działa (czujnik czadu, akceptowane ujęcia)', 'Wzorzec, który działa (czujnik czadu, akceptowane ujęcia): „katalog IKEA / kampania marki domowej”: jasne, naturalne światło dnia z kontrolowaną ekspozycją (nic nie jest prześwietlone), pełne i zamieszkałe wnętrze z kolorowymi akcentami, ludzie w trakcie czynności z prawdziwą emocją, produkt jako naturalna część sceny.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:czego-unikac-odrzucone-ujecia', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 109, date '2026-10-27', 'creative', array['plan', 'prompt']::text[], 'category', array['czujnik', 'czad', 'gasnic', 'alarm', 'bezpieczen', 'detektor']::text[], 'knowledge', false, 'Czego unikać (odrzucone ujęcia)', 'Czego unikać (odrzucone ujęcia): prześwietlone okna i bramy, flary, puste „showroomowe” wnętrza, nierealne układy (kominek na środku salonu), zwykłe sceny bez akcji i emocji (alarm, sypialnia, montaż pod sufitem).'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:pora-roku-za-oknem', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 110, date '2026-10-27', 'creative', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Pora roku za oknem', 'Pora roku za oknem: produkt używany cały rok (kuchenka, przedpokój) → lato lub neutralna pora; zima tylko tam, gdzie naprawdę jest sednem (kominek, inhalacja). Zimowa aura w każdym ujęciu robi zestaw ponurym.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:korekty-dotycza-swojej-kategorii-maska-lakie', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 111, date '2026-10-29', 'recipes', '{}'::text[], 'global', '{}'::text[], 'code', false, 'Korekty dotyczą swojej kategorii (maska lakiernicza, 29.10)', 'Korekty dotyczą swojej kategorii (maska lakiernicza, 29.10): poprawka z jednego produktu (np. „jasno, jak katalog IKEA” przy czujniku czadu) nie może nadpisać przepisu innej kategorii. Najpierw przepis kategorii, potem korekty zapisane dla tej kategorii.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:przepis-kinowy-przemyslowy-narzedzia-sprzet', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 112, date '2026-10-27', 'recipes', '{}'::text[], 'recipe', array['industrial_cinematic']::text[], 'config', false, 'Przepis „kinowy przemysłowy” (narzędzia, sprzęt ochronny, warsztat)', 'Przepis „kinowy przemysłowy” (narzędzia, sprzęt ochronny, warsztat): ciemny warsztat z akcentami lamp, twarde światło kluczowe z boku i mocna kontra z tyłu; pył, mgiełka lakieru, iskry i wióry podświetlone w powietrzu; chłodne tło z ciepłym akcentem; niski, „bohaterski” kąt kamery; postać jako pewny siebie fachowiec w skupieniu, faktury skóry, pot, kurz na ubraniu; płytka głębia ostrości, ziarno filmowe. Jasne, równe światło dnia w zwykłym garażu daje tu efekt taniego stocku.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:z-referencji-narzedziowych-hitachi-ryobi-pil', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 113, date '2026-10-27', 'creative', array['plan', 'prompt']::text[], 'recipe', array['industrial_cinematic']::text[], 'knowledge', false, 'Z referencji narzędziowych (Hitachi, Ryobi, piły, siekiery)', 'Z referencji narzędziowych (Hitachi, Ryobi, piły, siekiery): produkt dominuje kadr z bardzo niskiego kąta (często 60–80% kadru), człowiek jest częściowy: dłonie, profil, sylwetka w nieostrości; styl reportażowy, światło zastane i praktyczne lampy, prawdziwe zużycie i kurz. Twarz na wprost, symetrycznie w środku kadru i efekty świecenia dają najbardziej sztuczny wynik (maska lakiernicza, ujęcie wizualizacji). Efekt działania pokazywać realnie (zakurzony filtr obok czystego, czysty ślad po masce na zakurzonej twarzy), a nie poświatą.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:obowiazkowe-detale-od-sprzedawcy-maska-lakie', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 114, date '2026-10-29', 'references', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Obowiązkowe: detale od sprzedawcy (maska lakiernicza, 29.10)', 'Obowiązkowe: detale od sprzedawcy (maska lakiernicza, 29.10). Każde zbliżenie detalu przysłane przez sprzedawcę (mocowanie, wnętrze, uszczelka, paski, filtry osobno) dostaje własne ujęcie: detal skopiowany 1:1 z referencji, a zmienione tylko tło, światło i klimat na styl zestawu. Zestaw = mieszanka ujęć użycia i ujęć detali, mniej więcej po połowie. Ujęcie zestawu pokazuje wszystkie elementy z góry lub z wysokiego kąta, nigdy z poziomu blatu. Ujęcia bez wyraźnego argumentu (np. zdjęta maska i twarz) są pomijane.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:skala-miekkich-produktow-bez-sztywnej-formy', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 115, date '2026-10-29', 'card_scale', array['card', 'plan', 'prompt']::text[], 'product_type', array['worek', 'worki', 'torba', 'torby', 'kosz', 'plandek', 'miekk']::text[], 'knowledge', false, 'Skala miękkich produktów bez sztywnej formy (worki, torby, kosze z plandeki, 29.10)', 'Skala miękkich produktów bez sztywnej formy (worki, torby, kosze z plandeki, 29.10): model spłaszcza je i zmniejsza do rozmiaru torby na zakupy. Opis „sięga do bioder” nie wystarcza. W każdym ujęciu potrzebne są: proporcja („wyższy niż szeroki, ok. 5:4”), porównanie z przedmiotem o znanej wysokości tuż obok (taczka, siedzisko krzesła ogrodowego 45 cm, kompostownik), porównanie z ciałem osób w kadrze (dorosły: do połowy uda/bioder; dziecko 8 lat: do klatki piersiowej). W detalach z bliska skala ginie, więc obok musi być element odniesienia (dłoń, buty, grabie). Uchwyty zawsze opisane jako „wyłącznie na zewnątrz, dokładnie dwa górne i jeden dolny”. Ogrody europejskie: bez amerykańskich domów z cegły i podjazdów z garażem na dwa auta.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:przepis-ogrod-i-plener-z-referencji-kosiarek', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 116, date '2026-10-29', 'recipes', '{}'::text[], 'recipe', array['garden_outdoor']::text[], 'config', false, 'Przepis „ogród i plener” (z referencji kosiarek, glebogryzarek, myjek, 29.10)', 'Przepis „ogród i plener” (z referencji kosiarek, glebogryzarek, myjek, 29.10): kamera przy samej trawie, rozmyte źdźbła na pierwszym planie, produkt duży i dominujący; ostre, czyste słońce i głęboko niebieskie niebo albo niskie słońce z kontrą; nasycona, ale naturalna zieleń, trawnik w pasy; nowoczesny polski dom (elewacja z drewna, płaski dach, duże przeszklenia), żywopłot z tui, kostka brukowa, drewutnia; ludzie w odzieży roboczej w kolorze beżu i oliwki, w skupieniu, nie pozują; materiał w ruchu (ziemia, liście, trawa, woda) w kontrze; przed i po na jednej powierzchni. Taras wieczorem: girlandy żarówek, poduszki, drewno, styl IKEA.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:blok-stylu-nie-moze-opisywac-konkretnego-mie', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 117, date '2026-10-30', 'prompt_build', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Blok stylu nie może opisywać konkretnego miejsca (worek ogrodowy, 30.10)', 'Blok stylu nie może opisywać konkretnego miejsca (worek ogrodowy, 30.10): szczegółowy opis domu we wspólnym bloku daje ten sam dom w każdym ujęciu. Wspólny blok opisuje tylko światło, klimat i jakość; miejsce opisuje się osobno w każdym ujęciu i każde jest inne („nowoczesny dom” wystarcza modelowi do różnorodności). Ogrody i podwórka zawsze pełne i zamieszkane jak we wnętrzach: rabaty, donice, meble ogrodowe, zabawki, rower, wąż ogrodowy, drzewa owocowe. Pusty trawnik z żywopłotem = stock.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:decyzje-02-11', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 118, date '2026-11-02', 'planning', array['plan', 'prompt', 'qc']::text[], 'global', '{}'::text[], 'knowledge', false, 'Decyzje (02.11)', 'Decyzje (02.11): zestaw celowo pokazuje produkt w różnych miejscach i sytuacjach (każdy kupujący ma szansę zobaczyć „swój” dom), bez jednej spójnej sesji. Bez automatycznej korekty koloru po generacji: cała jakość ma wynikać z promptu. Sceny pełne i ciepłe zamiast minimalistycznych. Drobne błędy modelu (szczegóły mocowań, odbicia) są akceptowane, o ile nie zmieniają produktu ani nie wprowadzają w błąd.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:przepis-swiateczna-aura-z-referencji-grafika', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 119, date '2026-11-03', 'recipes', '{}'::text[], 'recipe', array['christmas_aura']::text[], 'config', false, 'Przepis „świąteczna aura” (z referencji grafika, 03.11)', 'Przepis „świąteczna aura” (z referencji grafika, 03.11): jeden stół czy kominek z kilkoma ozdobami to za mało. Potrzebne warstwy: (1) pierwszy plan z rozmytymi gałązkami jodły, czerwonymi jarzębinami, bombkami, cynamonem i suszoną pomarańczą przy krawędziach kadru; (2) środek z produktem otoczonym gesto dekoracjami; (3) tło pełne złotego bokeh: girlandy z lampkami na każdej linii (półki, okno, kominek), choinka, świece; (4) za oknem gęsto padający śnieg; (5) unoszące się w powietrzu drobiny (śnieg, brokat, mąka) w smugach światła. Paleta: ciepłe złoto, głęboka czerwień, butelkowa zieleń, krem. Hasło gatunku: „bożonarodzeniowa kampania reklamowa, magiczna, bajkowa aura”.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:korekta-przepisu-swiatecznego-03-11', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 120, date '2026-11-03', 'recipes', array['plan', 'prompt']::text[], 'recipe', array['christmas_aura']::text[], 'knowledge', true, 'Korekta przepisu świątecznego (03.11)', 'Korekta przepisu świątecznego (03.11): pełne warstwy z drobinami w powietrzu, rekwizytami w każdym rogu i złotym filtrem dają kicz. Cel to klatka ze świątecznego spotu firm meblowych i cukierniczych: realistyczny dom, dekoracje w ilości, jaką mają prawdziwi ludzie, światło tylko z prawdziwych źródeł (lampki, świece, ogień, latarnie za oknem), ciepłe światła i chłodniejsze, głębokie cienie, umiarkowane nasycenie, ziarno filmowe. Brokat i drobiny tylko w kuli produktu, śnieg tylko za oknem. Rozmyty pierwszy plan najwyżej w co drugim ujęciu.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:zblizenie-fragmentu-jako-referencja-w-scenie', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 121, date '2026-11-03', 'references', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Zbliżenie fragmentu jako referencja w scenie z całym produktem (dziadek do orzechów, 03.11)', 'Zbliżenie fragmentu jako referencja w scenie z całym produktem (dziadek do orzechów, 03.11): dołączenie zbliżenia samej kuli sprawiło, że model wygenerował osobną kulę obok figurki albo skrócił figurkę. W ujęciach z całym produktem dołączamy tylko widoki całości, a prompt mówi wprost, że element jest częścią produktu („kula jest tułowiem figurki, jeden przedmiot”). Proporcja ujęć nastrojowych: zdjęcia z silnika trafiają do galerii wewnątrz aukcji, nie na miniaturę listingu (tam jest zdjęcie na białym tle, poza zakresem silnika). Ujęcia nastrojowe i ciemniejsze są więc w porządku; warunek jest jeden: w każdym ujęciu produkt jest rozpoznawalny i nie znika za ludźmi ani w cieniu.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:spojnosc-kotwic-skali', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 122, date '2026-10-27', 'card_scale', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Spójność kotwic skali', 'Spójność kotwic skali: przed wysłaniem promptu silnik sprawdza rachunkiem, czy kotwice się nie wykluczają (np. figurka 50 cm stojąca na podłodze nie może mieć kuli na wysokości twarzy klęczącego dziecka, ok. 75 cm; model rozwiąże sprzeczność, powiększając produkt). Podest (stołek, komoda) podnosi produkt do potrzebnej wysokości. Efekty graficzne funkcji (nutki, fale): mało, małe, w tonacji zdjęcia, bez kolorów tęczy i dodatków typu pięciolinia.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:sezon-uzycia', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 123, date '2026-10-27', 'planning', array['card', 'plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Sezon użycia', 'Sezon użycia: produkt całoroczny, którego używa się głównie w określonej porze (inhalator, nawilżacz = jesień i zima; wentylator = lato), w ujęciach z ludźmi pokazuje tę porę: śnieg i szron za oknem, ciepłe ubrania. Bez dekoracji świątecznych.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:kadr-z-wnetrza-pojemnika', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 124, date '2026-10-27', 'planning', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Kadr z wnętrza pojemnika', 'Kadr z wnętrza pojemnika tylko wtedy, gdy otwór leży na osi kamery (torba na butelki z góry, bęben pralki). Torebka z zamkiem otwierana od góry = kadr z góry, nie z boku.'),
  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:mgielka-para-dym', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 125, date '2026-10-27', 'creative', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Mgiełka, para, dym', 'Mgiełka, para, dym: opisywać prędkość i zachowanie („powolny, miękki obłok jak oddech na mrozie”), nigdy „strumień” ani linie przepływu, bo daje to efekt spryskiwacza. Zawsze wskazać jedyne miejsce, z którego wylatuje.'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:zanim-powstanie-plan-ujec-silnik-przechodzi', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 126, date '2026-10-27', 'planning', array['plan']::text[], 'global', '{}'::text[], 'knowledge', false, 'Zanim powstanie plan ujęć, silnik przechodzi tę listę i…', 'Zanim powstanie plan ujęć, silnik przechodzi tę listę i zapisuje odpowiedzi w karcie produktu. Zasady nie są przypominane z pamięci, tylko odhaczane.'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:kategoria-przepis-stylu-i-jego-swiatlo-tabel', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 127, date '2026-10-27', 'planning', array['plan']::text[], 'global', '{}'::text[], 'knowledge', false, 'Kategoria → przepis stylu i jego światło (tabela przepisów)', 'Kategoria → przepis stylu i jego światło (tabela przepisów).'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:sezon-produktu-i-sezon-uzycia', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 128, date '2026-10-27', 'planning', array['plan']::text[], 'global', '{}'::text[], 'knowledge', false, 'Sezon produktu i sezon użycia', 'Sezon produktu i sezon użycia.'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:rozklad-swiatla-w-zestawie-ile-ujec-w-ktorym', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 129, date '2026-10-27', 'light_color', array['plan']::text[], 'global', '{}'::text[], 'code', false, 'Rozkład światła w zestawie: ile ujęć w którym świetle…', 'Rozkład światła w zestawie: ile ujęć w którym świetle (maks. 2 w złotej godzinie).'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:rozklad-typow-kadru-ten-sam-typ-maks-2-razy', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 130, date '2026-10-27', 'planning', array['plan']::text[], 'global', '{}'::text[], 'code', false, 'Rozkład typów kadru: ten sam typ maks. 2 razy', 'Rozkład typów kadru: ten sam typ maks. 2 razy.'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:kazde-ujecie-ma-kierunek-z-tabeli-kierunkow', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 131, date '2026-10-27', 'anti_stock', array['plan']::text[], 'global', '{}'::text[], 'template', false, 'Każde ujęcie ma kierunek z tabeli kierunków kreatywnych i…', 'Każde ujęcie ma kierunek z tabeli kierunków kreatywnych i przechodzi kontrolę anty-stock.'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:referencja-wybrana-wedlug-strony-produktu-wi', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 132, date '2026-10-27', 'references', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Referencja wybrana według strony produktu widocznej z kamery; akcesoria…', 'Referencja wybrana według strony produktu widocznej z kamery; akcesoria połączone opisane jako jeden przedmiot z liczbą sztuk.'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:efekt-dzialania-i-przed-po-tam-gdzie-produkt', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 133, date '2026-10-27', 'planning', array['plan']::text[], 'global', '{}'::text[], 'knowledge', false, 'Efekt działania i przed/po tam, gdzie produkt rozwiązuje problem', 'Efekt działania i przed/po tam, gdzie produkt rozwiązuje problem.'),
  ('grovbase-shot-spec:procedura-przed-kazdym-produ:uczciwosc-zawartosc-zestawu-wiek-skala-bez-o', 'Przepisy stylu › Procedura przed każdym produktem (obowiązkowa)', 134, date '2026-10-27', 'planning', array['plan']::text[], 'global', '{}'::text[], 'knowledge', false, 'Uczciwość: zawartość zestawu, wiek, skala, bez obietnic zdrowotnych', 'Uczciwość: zawartość zestawu, wiek, skala, bez obietnic zdrowotnych.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:prompt-sklada-sie-z-modulow-w-stalej-kolejno', 'Etap 3: wzorzec promptu', 135, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'Prompt składa się z modułów w stałej kolejności: produkt…', 'Prompt składa się z modułów w stałej kolejności: produkt i skala na początku, klimat krótko, stopka na końcu. Wcześniej opis wnętrza zajmował większość promptu i model traktował go jako ważniejszy od produktu.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:kierunek-blok-klimatu-z-przepisu-stylu', 'Etap 3: wzorzec promptu', 136, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'KIERUNEK (blok klimatu z przepisu stylu)', 'KIERUNEK (blok klimatu z przepisu stylu). Zaczyna się hasłem gatunku, np. „edytorska kampania lifestyle premium marki beauty. Prawdziwe zdjęcie, nie render (raw photo)”.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:produkt-blok-produktu-z-karty', 'Etap 3: wzorzec promptu', 137, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'PRODUKT (blok produktu z karty)', 'PRODUKT (blok produktu z karty). „Identyczny jak na zdjęciu 1”, budowa w kolejności elementów, kolor, napisy („wierny albo nieczytelny, nigdy przekręcony”), czego produkt NIE jest („to nie jest mebel z płyty”), zakaz kopiowania dodatków z referencji.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:skala', 'Etap 3: wzorzec promptu', 138, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'SKALA', 'SKALA. Wymiary w cm i calach + porównanie z przedmiotem tuż obok produktu (kubek, butelka 2 l, klamka, dłoń). W szerokich kadrach proporcja do ściany lub mebla. Przy produktach prawie kwadratowych główną kotwicą jest proporcja, nie sama wysokość.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:stan-chwyt', 'Etap 3: wzorzec promptu', 139, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'STAN / CHWYT', 'STAN / CHWYT. W jakim stanie jest produkt. Przy produkcie w dłoni: która część dotyka skóry lub powierzchni, gdzie jest dłoń, gdzie drugi koniec. Bez porównań do przedmiotów o innym kształcie („jak długopis” zbudowało długopis).'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:moment', 'Etap 3: wzorzec promptu', 140, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'MOMENT', 'MOMENT. Konkretna sytuacja z argumentem sprzedażowym i elementem ruchu.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:kadr', 'Etap 3: wzorzec promptu', 141, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'KADR', 'KADR. Format, kąt kamery w stopniach, wysokość, odległość, obiektyw, położenie elementów w procentach kadru. Obiektyw 50–100 mm dla produktów; szeroki kąt podbija skalę obiektu na pierwszym planie.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:postac', 'Etap 3: wzorzec promptu', 142, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'POSTAĆ', 'POSTAĆ. Wiek, wygląd, ubiór, mimika; „nikt nie patrzy w obiektyw”, chyba że ujęcie lustra.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:scenografia', 'Etap 3: wzorzec promptu', 143, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'SCENOGRAFIA', 'SCENOGRAFIA. W ujęciach szerokich konkretne elementy; w zbliżeniach tylko jako rozmyte plamy koloru i światła.'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:stopka-jakosci', 'Etap 3: wzorzec promptu', 144, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'STOPKA jakości', 'STOPKA jakości. Zawsze, w wariancie do typu ujęcia (poniżej).'),
  ('grovbase-shot-spec:etap-3-wzorzec-promptu:negative-prompt', 'Etap 3: wzorzec promptu', 145, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'NEGATIVE PROMPT', 'NEGATIVE PROMPT. Wspólna baza + ryzyka z karty produktu.'),
  ('grovbase-shot-spec:referencje:dolaczane-tylko-zdjecia-wskazane-w-planie-w', 'Etap 3: wzorzec promptu › Referencje', 146, date '2026-10-27', 'references', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'code', false, 'Dołączane tylko zdjęcia wskazane w planie, w ustalonej kolejności…', 'Dołączane tylko zdjęcia wskazane w planie, w ustalonej kolejności; prompt odwołuje się do nich jako „zdjęcie 1”, „zdjęcie 2”.'),
  ('grovbase-shot-spec:referencje:zwykle-2-referencje-glowna-stan-produktu-w-u', 'Etap 3: wzorzec promptu › Referencje', 147, date '2026-10-27', 'references', array['plan']::text[], 'global', '{}'::text[], 'knowledge', false, 'Zwykle 2 referencje: główna (stan produktu w ujęciu) +…', 'Zwykle 2 referencje: główna (stan produktu w ujęciu) + uzupełniająca (efekt użycia albo całość).'),
  ('grovbase-shot-spec:referencje:referencje-tylko-z-tym-samym-stanem-produktu', 'Etap 3: wzorzec promptu › Referencje', 148, date '2026-10-27', 'references', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'code', false, 'Referencje tylko z tym samym stanem produktu co w…', 'Referencje tylko z tym samym stanem produktu co w scenie.'),
  ('grovbase-shot-spec:referencje:przy-zblizeniu-zawsze-rowniez-zdjecie-calosc', 'Etap 3: wzorzec promptu › Referencje', 149, date '2026-10-27', 'references', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'code', false, 'Przy zbliżeniu zawsze również zdjęcie całości', 'Przy zbliżeniu zawsze również zdjęcie całości.'),
  ('grovbase-shot-spec:stopki-jakosci:stopka-zawsze-jest-w-prompcie-w-testach-daje', 'Etap 3: wzorzec promptu › Stopki jakości', 150, date '2026-10-27', 'prompt_build', array['prompt']::text[], 'global', '{}'::text[], 'template', false, 'Stopka zawsze jest w prompcie: w testach daje wyraźną…', 'Stopka zawsze jest w prompcie: w testach daje wyraźną poprawę realizmu i światła.')
) as v(rule_key, section, position, source_date, topic, stages, scope_kind, scope_values, delivery, is_correction, title, body)
where (select ks.id from public.knowledge_sources ks where ks.set_id = (select id from public.knowledge_sets where name = 'GrovBase Shot – specyfikacja silnika lifestyle' order by created_at limit 1) and ks.doc_key = 'grovbase-shot-spec' and ks.version = 1 and ks.format = 'md') is not null
on conflict (rule_key, revision) do nothing;
